shell_commands.command:
cd /testbed && apply_patch <<'PATCH'
*** Begin Patch
*** Add File: test/transform/resource/before/UtilityClassGeneric.java
+@lombok.experimental.UtilityClass
+class UtilityClassGeneric {
+	<T> T convertValue(Class<T> toValueType) {
+		return null;
+	}
+	
+	DTO convert(Object json) {
+		return convertValue(DTO.class);
+	}
+	
+	Object convert(DTO dto) {
+		return null;
+	}
+	
+	class DTO {
+	}
+}
*** Add File: test/transform/resource/after-delombok/UtilityClassGeneric.java
+final class UtilityClassGeneric {
+	static <T> T convertValue(Class<T> toValueType) {
+		return null;
+	}
+	static DTO convert(Object json) {
+		return convertValue(DTO.class);
+	}
+	static Object convert(DTO dto) {
+		return null;
+	}
+	static class DTO {
+	}
+	@java.lang.SuppressWarnings("all")
+	private UtilityClassGeneric() {
+		throw new java.lang.UnsupportedOperationException("This is a utility class and cannot be instantiated");
+	}
+}
*** Add File: test/transform/resource/after-ecj/UtilityClassGeneric.java
+final @lombok.experimental.UtilityClass class UtilityClassGeneric {
+  static class DTO {
+    DTO() {
+      super();
+    }
+  }
+  static <T>T convertValue(Class<T> toValueType) {
+    return null;
+  }
+  static DTO convert(Object json) {
+    return convertValue(DTO.class);
+  }
+  static Object convert(DTO dto) {
+    return null;
+  }
+  private @java.lang.SuppressWarnings("all") UtilityClassGeneric() {
+    super();
+    throw new java.lang.UnsupportedOperationException("This is a utility class and cannot be instantiated");
+  }
+}
*** End Patch
PATCH
ant test.javacCurrent > /tmp/lombok-utility-baseline.log 2>&1; result=$?; tail -n 95 /tmp/lombok-utility-baseline.log; exit "$result"

cd /testbed && python3 - <<'PY'
from pathlib import Path
files = {
'before': '''@lombok.experimental.UtilityClass
class UtilityClassGeneric {
	<T> T convertValue(Class<T> toValueType) {
		return null;
	}

	DTO convert(Object json) {
		return convertValue(DTO.class);
	}

	Object convert(DTO dto) {
		return null;
	}

	class DTO {
	}
}
''',
'after-delombok': '''final class UtilityClassGeneric {
	static <T> T convertValue(Class<T> toValueType) {
		return null;
	}
	static DTO convert(Object json) {
		return convertValue(DTO.class);
	}
	static Object convert(DTO dto) {
		return null;
	}
	static class DTO {
	}
	@java.lang.SuppressWarnings("all")
	private UtilityClassGeneric() {
		throw new java.lang.UnsupportedOperationException("This is a utility class and cannot be instantiated");
	}
}
''',
'after-ecj': '''final @lombok.experimental.UtilityClass class UtilityClassGeneric {
  static class DTO {
    DTO() {
      super();
    }
  }
  static <T>T convertValue(Class<T> toValueType) {
    return null;
  }
  static DTO convert(Object json) {
    return convertValue(DTO.class);
  }
  static Object convert(DTO dto) {
    return null;
  }
  private @java.lang.SuppressWarnings("all") UtilityClassGeneric() {
    super();
    throw new java.lang.UnsupportedOperationException("This is a utility class and cannot be instantiated");
  }
}
'''
}
for directory, text in files.items():
    p = Path('test/transform/resource') / directory / 'UtilityClassGeneric.java'
    with p.open('x') as out:
        out.write(text)
PY
ant test.javacCurrent > /tmp/lombok-utility-baseline.log 2>&1; result=$?; grep -n -A 75 -B 5 -E '\[FAIL\]|NullPointerException|UtilityClassGeneric|BUILD FAILED' /tmp/lombok-utility-baseline.log | tail -n 140; exit "$result"

